#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node *head = NULL;

// Create new node
struct Node* createNode(int value) {
    struct Node *newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = newNode; // circular
    return newNode;
}

// Insert at position
void insertAtPos(int value, int pos) {
    struct Node *newNode = createNode(value);

    if (head == NULL) {   // first node
        head = newNode;
        return;
    }

    if (pos == 1) { // insert at beginning
        struct Node *temp = head;
        while (temp->next != head)
            temp = temp->next;

        newNode->next = head;
        temp->next = newNode;
        head = newNode;
        return;
    }

    struct Node *temp = head;
    for (int i = 1; i < pos - 1; i++) {
        if (temp->next == head) break; // reached end
        temp = temp->next;
    }

    newNode->next = temp->next;
    temp->next = newNode;
}

// Delete at position
void deleteAtPos(int pos) {
    if (head == NULL) {
        printf("List empty!\n");
        return;
    }

    struct Node *temp = head;

    if (pos == 1) { // delete first
        if (head->next == head) { // only one node
            free(head);
            head = NULL;
            return;
        }

        struct Node *last = head;
        while (last->next != head)
            last = last->next;

        head = head->next;
        last->next = head;
        free(temp);
        return;
    }

    struct Node *prev = NULL;
    for (int i = 1; i < pos && temp->next != head; i++) {
        prev = temp;
        temp = temp->next;
    }

    if (prev == NULL) return; // invalid pos

    prev->next = temp->next;
    free(temp);
}

// Display
void display() {
    if (head == NULL) {
        printf("List empty!\n");
        return;
    }

    struct Node *temp = head;
    printf("List: ");
    do {
        printf("%d ", temp->data);
        temp = temp->next;
    } while (temp != head);

    printf("\n");
}

// Main
int main() {
    int choice, val, pos;

    while (1) {
        printf("\n1.Insert\n2.Delete\n3.Display\n4.Exit\nEnter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter data: ");
                scanf("%d", &val);
                printf("Enter position: ");
                scanf("%d", &pos);
                insertAtPos(val, pos);
                break;

            case 2:
                printf("Enter position: ");
                scanf("%d", &pos);
                deleteAtPos(pos);
                break;

            case 3:
                display();
                break;

            case 4:
                exit(0);

            default:
                printf("Invalid choice!\n");
        }
    }
    return 0;
}
```

