### ✅ **Reverse CLL – Simplest Function**

```c
void reverseCLL() {
    if (head == NULL || head->next == head)
        return;

    struct Node *prev = NULL, *curr = head, *next;

    // Break the circle first
    struct Node *last = head;
    while (last->next != head)
        last = last->next;
    last->next = NULL;

    // Normal SLL reverse
    while (curr != NULL) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }

    // Connect last back to new head
    head = prev;
    last = head;
    while (last->next != NULL)
        last = last->next;
    last->next = head;
}
```

